input.command:
python3 - <<'PY'
import csv
rows=list(csv.DictReader(open('.tmp/joined.csv')))
mism={f:0 for f in ['f1','f2','f3','f4','f5']}
ex={}
for r in rows:
    for f in mism:
        a=float(r[f]); b=float(r['srv_'+f])
        if abs(a-b)>1e-6:
            mism[f]+=1
            if f not in ex: ex[f]=(a,b)
print("rows",len(rows))
print("mismatch counts",mism)
print("examples",ex)
PY

